import SwiftUI
import Combine
import Foundation
import CompositorServices
import UntoldEngineXR



// Simple owner so the XR system doesn't deallocate.
final class XRHolder {
    static let shared = XRHolder()
    var xr: UntoldEngineXR?
    var renderThread: Thread?
    var gameScene: GameScene?
}

struct UntoldEngineConfiguration: CompositorLayerConfiguration {
    func makeConfiguration(capabilities: LayerRenderer.Capabilities,
                           configuration: inout LayerRenderer.Configuration) {
        configuration.layout = .dedicated
        configuration.isFoveationEnabled = false
        configuration.colorFormat = .bgra8Unorm_srgb
    }
}

@main
struct ImmersiveGolApp: App {

    @State private var immersionStyle: ImmersionStyle = .mixed

    var body: some Scene {
        WindowGroup {
            ContentView()
        }
        .windowStyle(.plain)
        .defaultSize(width: 640, height: 650)

        WindowGroup("Engine Stats", id: "EngineStatsPanel") {
            EngineStatsWindowView(store: EngineStatsWindowStore.shared)
        }
        .defaultSize(width: 720, height: 340)

    ImmersiveSpace(id: "ImmersiveSpace") {

        CompositorLayer(configuration: UntoldEngineConfiguration(), renderer: { layerRenderer in

            // init + retain XR system
            if XRHolder.shared.xr == nil {

                guard let physics = GameScene.installPhysics() else { return }
                if let xr = UntoldEngineXR(layerRenderer: layerRenderer) {
                    XRHolder.shared.xr = xr

                    // Set engine's immersion mode to mixed (passthrough)
                    xr.setImmersionMode(xrImmersionMode: .mixed)

                    // Initialize game scene
                    let gameScene = GameScene(physics: physics)
                    XRHolder.shared.gameScene = gameScene

                    // Setup callbacks
                    xr.setupCallbacks(
                        gameUpdate: { deltaTime in
                            gameScene.update(deltaTime: deltaTime)
                        },
                        handleInput: {
                            gameScene.handleInput()
                        }
                    )

                    let t = Thread {
                        xr.start()      // sets isRunning = true
                        xr.runLoop()    // blocking loop - runs on dedicated thread, NOT MainActor
                        gameScene.shutdown()
                        Task { @MainActor in
                            XRHolder.shared.gameScene = nil
                            XRHolder.shared.renderThread = nil
                            XRHolder.shared.xr = nil
                        }
                    }
                    t.name = "XR Render Thread"
                    t.qualityOfService = .userInteractive
                    XRHolder.shared.renderThread = t
                    t.start()
                }
            }
        })
    }
        .immersionStyle(selection: $immersionStyle, in: .mixed)
        // Glove visuals replace the hands; prevent the system's hand overlay
        // from being composited in front of them (same approach as CoolWeb).
        .upperLimbVisibility(.hidden)
    }
}

struct ContentView: View {
    @Environment(\.openImmersiveSpace) private var openImmersiveSpace
    @State private var experienceOpen = false
    @State private var opening = false
    @State private var runtimeObserved = false
    @State private var floorPlaced = false
    @State private var kicking = false
    @State private var shotStatus = "Start the experience to place your stadium"
    private let statusTimer = Timer.publish(every: 0.2, on: .main, in: .common).autoconnect()

    var body: some View {
        VStack(spacing: 24) {
            Text("ImmersiveGol")
                .font(.extraLargeTitle)
                .fontWeight(.bold)
            if !experienceOpen {
                Button("Start Experience") {
                    opening = true
                    Task {
                        let result = await openImmersiveSpace(id: "ImmersiveSpace")
                        if case .opened = result {
                            experienceOpen = true
                            shotStatus = "Look at the ground, then pinch and release to place the stadium"
                        }
                        opening = false
                    }
                }
                .disabled(opening)
                .buttonStyle(.borderedProminent)
            } else {
                if !floorPlaced {
                    Text("Look at the ground, then pinch and release.")
                        .font(.title2)
                    Text("The stadium will appear after the floor is detected.")
                        .foregroundStyle(.secondary)
                }
                HStack(spacing: 16) {
                    Button("Start Kicking") {
                        XRHolder.shared.gameScene?.startKicking()
                    }
                    .buttonStyle(.borderedProminent)
                    .disabled(!floorPlaced || kicking)
                    Button("Stop Kicking") {
                        XRHolder.shared.gameScene?.stopKicking()
                    }
                    .buttonStyle(.bordered)
                    .disabled(!kicking)
                }
            }
            Text(shotStatus)
                .font(.headline)
        }
        .controlSize(.large)
        .padding(30)
        .onReceive(statusTimer) { _ in
            let game = XRHolder.shared.gameScene
            floorPlaced = game?.isFloorPlaced ?? false
            kicking = game?.isKicking ?? false
            if let game {
                // Recover if this window was recreated while XR was running.
                runtimeObserved = true
                experienceOpen = true
                shotStatus = game.shotStatus
            } else if runtimeObserved, XRHolder.shared.xr == nil {
                // An opened space may still be initializing its renderer. Only
                // treat missing runtime state as closure after seeing it run.
                runtimeObserved = false
                experienceOpen = false
                shotStatus = "Start the experience to place your stadium"
            }
        }
    }
}

struct EngineStatsWindowView: View {
    @ObservedObject var store: EngineStatsWindowStore

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack {
                Text("Engine Stats")
                    .font(.headline)
                Spacer()
                Toggle("Advanced", isOn: $store.advancedMode)
                    .toggleStyle(.switch)
                    .controlSize(.small)
            }

            ScrollView {
                Text(store.advancedMode ? store.expandedText : store.compactText)
                    .font(.system(size: 12, design: .monospaced))
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .textSelection(.enabled)
            }
        }
        .padding(16)
    }
}
